async function saveAudioToStorageAndCache(cacheKey: string, audioBuffer: Buffer): Promise<string | null> {
  try {
     const fileName = `${cacheKey}.mp3`;
     const uploadUrl = `${supabaseUrl}/storage/v1/object/audio_cache/${fileName}`;
     await axios.post(uploadUrl, audioBuffer, {
        headers: {
           apikey: supabaseServiceKey,
           Authorization: `Bearer ${supabaseServiceKey}`,
           'Content-Type': 'audio/mpeg',
           // Stessa chiave = stesso testo+voce: sovrascrivere è corretto
           // (rigenerazione di una entry vuota/corrotta).
           'x-upsert': 'true'
        }
     });
     const publicUrl = `${supabaseUrl}/storage/v1/object/public/audio_cache/${fileName}`;
     await saveToCache(cacheKey, 'audio_guide', null, publicUrl);
     return publicUrl;
  } catch(e: any) {
     console.error("Audio cache upload error:", e.response?.data || e.message);
     return null;
  }
}

// La cache api_cache passa ai feed eventi (eventiFeed.ts non conosce Supabase).
eventiFeed.configuraEventiFeed({
  get: (k: string) => getFromCache(k),
  set: (k: string, tipo: string, v: any) => saveToCache(k, tipo, v),
});

export const app = express();
// SICUREZZA: dietro il proxy Vercel/Express, req.ip deriva da X-Forwarded-For
// SOLO con trust proxy attivo. Senza, il rate limiter chiavava sull'header grezzo
// x-forwarded-for (spoofabile: un attaccante lo cambia a ogni richiesta e aggira
// del tutto il limite). Con trust proxy Express calcola req.ip in modo coerente.
app.set('trust proxy', true);
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

  // --- CORS CON ALLOWLIST DINAMICA ---
  // Prima vercel.json rispondeva Access-Control-Allow-Origin: * a tutti: un
  // qualsiasi sito poteva bruciare le API (Groq/DeepSeek/Azure/Unsplash) dal
  // browser dei suoi visitatori. Non si può però mettere un origin FISSO:
  // romperebbe le app native (WebView Capacitor con origin capacitor://localhost
  // o https://localhost). Si riflette quindi l'origin SOLO se in allowlist;
  // le richieste senza Origin (server-to-server, Stripe/RevenueCat, curl) non
  // sono soggette a CORS e passano comunque. L'header statico è stato tolto da
  // vercel.json (questo middleware è l'unica autorità).
  const CORS_ALLOWLIST = new Set([
    'https://wip.guide',
    'https://www.wip.guide',
    'https://itainta.vercel.app',
    'capacitor://localhost',
    'ionic://localhost',
    'http://localhost',
    'https://localhost',
  ]);
  const isAllowedOrigin = (origin?: string): boolean => {
    if (!origin) return false; // nessun Origin = non una richiesta browser CORS
    if (CORS_ALLOWLIST.has(origin)) return true;
    // localhost con porta (dev: 3000/5173) e preview *.vercel.app del progetto
    if (/^https?:\/\/localhost(:\d+)?$/.test(origin)) return true;
    if (/^https:\/\/itainta[a-z0-9-]*\.vercel\.app$/.test(origin)) return true;
    return false;
  };
  app.use((req, res, next) => {
    const origin = req.headers.origin as string | undefined;
    if (isAllowedOrigin(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin as string);
      res.setHeader('Vary', 'Origin');
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
      res.setHeader('Access-Control-Allow-Headers', 'Authorization, apikey, X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version');
    }
    if (req.method === 'OPTIONS') { res.status(204).end(); return; }
    next();
  });

  // --- STRIPE WEBHOOK (Must be before express.json) ---
  // Prezzario autorevole lato server: il client NON deve poter dettare
  // quanti crediti riceve per quanti euro. `cents` = importo Stripe reale,
  // `credits` = crediti accreditati. Prima unit_amount era limitato a 3 casi
  // ma metadata.amount (il valore accreditato) veniva dal body → amount:100000
  // costava 19,99€ e accreditava 100.000 crediti. Tenere allineato a
  // src/lib/pricing.ts e al mapping RevenueCat.
  // Prezzi ALLINEATI a Google Play/RevenueCat (30/08/2026, richiesta del
  // committente): lo stesso pacchetto deve costare uguale sul web (Stripe) e
  // nell'app (store). Se si ritoccano i prezzi su Play/RevenueCat vanno
  // aggiornati anche qui: /api/shop/pacchetti e il Checkout leggono questa
  // tabella.
  const CREDIT_PACKS: Record<string, { credits: number; cents: number }> = {
    package_500:  { credits: 500,  cents: 599 },
    package_1100: { credits: 1100, cents: 1199 },
    package_2600: { credits: 2600, cents: 2399 },
    package_2500: { credits: 2500, cents: 2399 }, // storico Google Play
  };
  const packFromAmount = (amt: number) =>
    Object.values(CREDIT_PACKS).find(p => p.credits === amt);

  // Accredito atomico e idempotente (RPC credit_purchase): rimpiazza il
  // GET purchased_credits + PATCH (current+amount) che era soggetto a lost
  // update contro i consumi concorrenti. L'idempotenza vive nell'unique
  // index (source, event_id), non più nel marker su api_cache.
  const creditPurchase = async (userId: string, amount: number, source: string, eventId: string | null, description?: string): Promise<boolean> => {
    const rpc = await axios.post(
      `${supabaseUrl}/rest/v1/rpc/credit_purchase`,
      { p_user_id: userId, p_amount: amount, p_source: source, p_event_id: eventId, p_description: description || null },
      { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json' } }
    );
    const ok = rpc.data === true;
    // Unico punto per Stripe E RevenueCat: vedi capturaEvento più sopra.
    if (ok) capturaEvento(userId, 'credits_purchased', { amount, source });
    return ok;
  };

  app.post('/api/stripe/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
    const sig = req.headers['stripe-signature'];
    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

    if (!stripeClient || !webhookSecret) {
      return res.status(400).send('Stripe non configurato');
    }

    let event;
    try {
      event = stripeClient.webhooks.constructEvent(req.body, sig, webhookSecret);
    } catch (err: any) {
      console.error('Webhook signature verification failed.', err.message);
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    // Idempotenza a due livelli: l'accredito crediti è protetto atomicamente
    // dall'unique index (source, event_id) dentro credit_purchase; per i rami
    // NON-crediti (coupon B2B, subscription) resta il marker su api_cache, ma
    // scritto SOLO a fine elaborazione riuscita (vedi in coda) così un
    // fallimento non blocca per sempre il retry di Stripe.
    const evtKey = `stripe_evt_${event.id}`;
    if (await getFromCache(evtKey)) {
      return res.json({ received: true, duplicate: true });
    }

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object as any;
      const userId = session.client_reference_id;
      const amountStr = session.metadata?.amount;

      if (session.metadata?.b2b === "true") {
        // Acquisto B2B: generazione coupon per la struttura (logica migrata dal
        // vecchio /api/webhook non firmato, ora dismesso).
        const codeCount = parseInt(session.metadata.codeCount || "0");
        const structureName = session.metadata.structureName || "Struttura Sconosciuta";
        const durationDays = parseInt(session.metadata.durationDays || "7");
        // I pacchetti B2B sono voucher CREDITI: ogni coupon regala crediti
        // all'ospite (non giorni premium). duration_days resta per compat.
        const creditsPerVoucher = parseInt(session.metadata.creditsPerVoucher || "500");
        if (codeCount > 0) {
          try {
            const coupons = Array.from({ length: codeCount }).map(() => ({
              code: crypto.randomBytes(4).toString('hex').toUpperCase(),
              duration_days: durationDays,
              reward_credits: creditsPerVoucher,
              max_uses: 1,
              structure_name: structureName,
              is_active: true
            }));
            await axios.post(`${supabaseUrl}/rest/v1/coupons`, coupons, {
              headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, Prefer: 'return=minimal' }
            });
            console.log(`[Stripe Webhook] Generated ${codeCount} coupons for ${structureName}`);
          } catch (e: any) {
            console.error('[Stripe Webhook] Error generating coupons:', e.message);
            await logSystemError('critical', `Stripe B2B: generazione coupon fallita dopo il pagamento: ${e.message}`, {
              source: 'stripe-webhook', structureName, codeCount, stack: e.stack
            });
          }
        }
      } else if (userId && amountStr) {
        const amount = parseInt(amountStr, 10);
        try {
          // Accredito atomico e idempotente. Non serve marker: il retry di
          // Stripe che rientra qui trova la riga (source,event_id) già scritta
          // e credit_purchase ritorna true senza raddoppiare.
          const ok = await creditPurchase(userId, amount, 'stripe', event.id, `Checkout ${session.id || ''}`.trim());
          if (!ok) throw new Error('credit_purchase returned false');
          console.log(`[Stripe] Credited ${amount} to user ${userId}`);
        } catch (e: any) {
          console.error('[Stripe Webhook] Error updating credits:', e.message);
          // Pagamento riuscito ma accredito fallito: NON scrivere il marker e
          // rispondere 500, così Stripe ritenta (l'accredito è idempotente).
          await logSystemError('critical', `Stripe: pagamento OK ma accredito crediti fallito: ${e.message}`, {
            source: 'stripe-webhook', userId, amount: amountStr, sessionId: session?.id, stack: e.stack
          });
          return res.status(500).json({ error: 'credit_grant_failed' });
        }
      } else if (userId) {
        // Abbonamento premium (checkout senza metadata.amount): attivazione profilo.
        try {
          let currentPeriodEnd = new Date();
          currentPeriodEnd.setMonth(currentPeriodEnd.getMonth() + 1);
          if (session.subscription) {
            const sub = await stripeClient.subscriptions.retrieve(session.subscription as string);
            currentPeriodEnd = new Date((sub as any).current_period_end * 1000);
          }
          await axios.post(`${supabaseUrl}/rest/v1/user_profiles`, {
            id: userId,
            subscription_status: 'active',
            subscription_tier: 'premium',
            current_period_end: currentPeriodEnd.toISOString(),
            stripe_customer_id: session.customer
          }, {
            headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, Prefer: 'resolution=merge-duplicates' }
          });
        } catch (e: any) {
          console.error('[Stripe Webhook] Error activating subscription:', e.message);
          await logSystemError('critical', `Stripe: attivazione abbonamento fallita: ${e.message}`, {
            source: 'stripe-webhook', userId, sessionId: session?.id, stack: e.stack
          });
        }
      }
    } else if (event.type === 'customer.subscription.deleted') {
      const session = event.data.object as any;
      try {
        await axios.patch(`${supabaseUrl}/rest/v1/user_profiles?stripe_customer_id=eq.${session.customer}`, {
          subscription_status: 'canceled',
          subscription_tier: 'free',
          current_period_end: null
        }, {
          headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }
        });
      } catch (e: any) {
        console.error('[Stripe Webhook] Error canceling subscription:', e.message);
      }
    } else if (event.type === 'invoice.payment_succeeded') {
      const session = event.data.object as any;
      try {
        if (session.subscription) {
          const sub = await stripeClient.subscriptions.retrieve(session.subscription as string);
          await axios.patch(`${supabaseUrl}/rest/v1/user_profiles?stripe_customer_id=eq.${session.customer}`, {
            subscription_status: 'active',
            current_period_end: new Date((sub as any).current_period_end * 1000).toISOString()
          }, {
            headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }
          });
        }
      } catch (e: any) {
        console.error('[Stripe Webhook] Error renewing subscription:', e.message);
      }
    }

    // Marker scritto SOLO ora, a elaborazione riuscita: il ramo crediti che
    // fallisce è già uscito con 500 sopra, quindi il retry di Stripe non lo
    // trova e riprova (l'accredito è comunque idempotente lato RPC).
    await saveToCache(evtKey, 'webhook_event', event.type);
    res.json({ received: true });
  });

  // --- REVENUECAT WEBHOOK (JSON) ---
  app.post('/api/revenuecat/webhook', express.json(), async (req, res) => {
    try {
      // Auth obbligatoria: senza questo check chiunque poteva accreditarsi
      // crediti con un semplice POST. Il valore va impostato sia qui
      // (REVENUECAT_WEBHOOK_SECRET) sia nella dashboard RevenueCat come
      // Authorization header del webhook.
      const expectedAuth = process.env.REVENUECAT_WEBHOOK_SECRET;
      if (!expectedAuth) {
        console.error('[RevenueCat Webhook] REVENUECAT_WEBHOOK_SECRET non configurato: webhook rifiutato');
        return res.status(503).json({ error: 'Webhook not configured' });
      }
      const authHeader = req.headers.authorization || '';
      // Confronto a tempo costante: un `!==` su stringhe fa scattare un return
      // anticipato al primo carattere diverso, quindi il tempo di risposta
      // rivela quanti caratteri iniziali sono corretti (timing attack) e
      // permette di indovinare il secret un carattere alla volta. Se le
      // lunghezze differiscono NON si chiama timingSafeEqual (che altrimenti
      // lancia): si considera direttamente il confronto fallito.
      const timingSafeStrEqual = (a: string, b: string): boolean => {
        const bufA = Buffer.from(a, 'utf8');
        const bufB = Buffer.from(b, 'utf8');
        if (bufA.length !== bufB.length) return false;
        return crypto.timingSafeEqual(bufA, bufB);
      };
      const isValidAuth = timingSafeStrEqual(authHeader, expectedAuth) || timingSafeStrEqual(authHeader, `Bearer ${expectedAuth}`);
      if (!isValidAuth) {
        console.warn('[RevenueCat Webhook] Tentativo con Authorization non valida');
        return res.status(401).json({ error: 'Unauthorized' });
      }

      const event = req.body?.event;
      
      // We only care about new non-renewing purchases (consumables)
      if (!event || (event.type !== 'NON_RENEWING_PURCHASE' && event.type !== 'INITIAL_PURCHASE')) {
        return res.json({ received: true, ignored: true });
      }

      const userId = event.app_user_id;
      // Google Play può inoltrare il product id col suffisso base plan
      // ("package_2600:base"): senza lo split il mapping sotto non matcha e
      // l'acquisto verrebbe ricevuto ma accreditato 0.
      const productId = String(event.product_id || '').split(':')[0];

      // Prezzario autorevole (stesso di Stripe): mai fidarsi del prodotto per
      // dedurre l'importo se non è mappato.
      const rcAmount = CREDIT_PACKS[productId]?.credits
        ?? (productId === 'crediti_500' ? 500 : 0);

      if (userId && rcAmount > 0) {
        try {
          // Accredito atomico e idempotente su (source='revenuecat', event_id).
          const ok = await creditPurchase(userId, rcAmount, 'revenuecat', event.id || null, `IAP ${productId || ''}`.trim());
          if (!ok) throw new Error('credit_purchase returned false');
          console.log(`[RevenueCat Webhook] Accreditati ${rcAmount} crediti all'utente ${userId} per acquisto Android di ${productId}`);
        } catch (e: any) {
          // Pagato su Google Play ma accredito fallito: 500 → RevenueCat ritenta.
          await logSystemError('critical', `RevenueCat: acquisto OK ma accredito fallito: ${e.message}`, {
            source: 'revenuecat-webhook', userId, productId, amount: rcAmount, stack: e.stack
          });
          return res.status(500).json({ error: 'credit_grant_failed' });
        }
      } else if (userId && event.type !== 'INITIAL_PURCHASE') {
        // Prodotto non mappato incassato: prima veniva accreditato 0 in
        // silenzio. Ora lascia traccia per l'admin (non blocca il 2xx).
        await logSystemError('warning', `RevenueCat: product_id non mappato, accredito 0`, {
          source: 'revenuecat-webhook', userId, productId
        });
      }

      res.json({ received: true });
    } catch (e: any) {
      console.error('[RevenueCat Webhook] Errore critico:', e.message);
      await logSystemError('critical', `RevenueCat: errore critico nel webhook acquisti Android: ${e.message}`, {
        source: 'revenuecat-webhook', eventType: req.body?.event?.type, productId: req.body?.event?.product_id, stack: e.stack
      });
      res.status(500).send('Error processing webhook');
    }
  });

  // Tetto GLOBALE del body JSON: 1 MB (audit SEC-06, 28/08/2026). Prima era
  // 50 MB per tutte le rotte: chiunque poteva tenere occupata la function con
  // payload enormi. Le sole rotte che ricevono immagini base64 (/api/vision)
  // montano INLINE un express.json({ limit: '12mb' }) prima dell'handler:
  // per loro il parser globale DEVE saltare, altrimenti risponderebbe 413 a
  // 1 MB prima che quello di rotta venga mai eseguito.
  // I webhook Stripe (express.raw) e RevenueCat sono registrati sopra e non
  // passano di qui.
  const jsonBodyPiccolo = express.json({ limit: "1mb" });
  const ROTTE_BODY_GRANDE = new Set(["/api/vision"]);
  app.use((req, res, next) => {
    if (ROTTE_BODY_GRANDE.has(req.path)) return next();
    return jsonBodyPiccolo(req, res, next);
  });

  // --- STRIPE CREATE CHECKOUT ---
  app.post('/api/stripe/create-checkout', async (req, res) => {
    try {
      const { userId, amount, priceId } = req.body;
      if (!stripeClient) {
        return res.status(500).json({ error: "Stripe non è configurato sul server" });
      }

      // Un Price ID Stripe vero inizia con 'price_'. Lo shop passa gli ID
      // pacchetto RevenueCat ('package_500' ecc.), che Stripe non conosce:
      // prima finivano in `line_items: [{ price: 'package_500' }]` e la
      // creazione della sessione falliva SEMPRE ("No such price").
      //
      // PREZZO E CREDITI DAL SERVER, MAI DAL BODY: prima unit_amount era
      // limitato a 3 casi ma metadata.amount (ciò che il webhook accredita)
      // veniva da req.body.amount → amount:100000 costava 19,99€ e dava
      // 100.000 crediti. Ora si deriva tutto dal pacchetto autorevole.
      let line_items = [];
      let creditedAmount: number;
      if (priceId && String(priceId).startsWith('price_') && priceId !== 'price_test') {
        // Price Stripe reale: i crediti restano quelli del pacchetto noto (se
        // riconducibile), altrimenti si rifiuta invece di indovinare.
        const pack = CREDIT_PACKS[String(priceId)] || packFromAmount(Number(amount));
        if (!pack) return res.status(400).json({ error: 'Pacchetto non valido' });
        creditedAmount = pack.credits;
        line_items = [{ price: priceId, quantity: 1 }];
      } else {
        const pack = CREDIT_PACKS[String(priceId)] || packFromAmount(Number(amount));
        if (!pack) return res.status(400).json({ error: 'Pacchetto non valido' });
        creditedAmount = pack.credits;
        line_items = [{
          price_data: {
            currency: 'eur',
            product_data: { name: `Pacchetto ${pack.credits} Crediti` },
            unit_amount: pack.cents,
          },
          quantity: 1,
        }];
      }

      const host = req.headers.host || 'localhost:3000';
      const protocol = req.protocol || 'http';

      const session = await stripeClient.checkout.sessions.create({
        // Solo 'card': Apple Pay / Google Pay NON sono payment_method_types
        // validi (Stripe rifiutava l'intera richiesta); i wallet compaiono
        // comunque automaticamente nella pagina di Checkout.
        payment_method_types: ['card'],
        line_items,
        mode: 'payment',
        success_url: `${protocol}://${host}/?payment=success`,
        cancel_url: `${protocol}://${host}/?payment=cancel`,
        client_reference_id: userId,
        metadata: {
          // Valore AUTOREVOLE derivato dal pacchetto, non dal body.
          amount: creditedAmount.toString()
        }
      });

      // `url` permette al client il redirect diretto senza chiave pubblica
      // Stripe.js; sessionId resta per il vecchio percorso redirectToCheckout.
      res.json({ sessionId: session.id, url: session.url });
    } catch (e: any) {
      console.error('Create checkout error:', e);
      res.status(500).json({ error: e.message });
    }
  });

  // Listino PUBBLICO dei pacchetti crediti per il web (30/08/2026): lo shop
  // mostrava «Prezzo al pagamento» perche' non voleva cablare un importo
  // diverso da quello addebitato. L'importo autorevole e' CREDIT_PACKS, la
  // stessa tabella che /api/stripe/create-checkout mette in unit_amount:
  // esporla qui rende i due valori identici per costruzione. Sul nativo
  // continua a valere il priceString dello store (RevenueCat).
  app.get('/api/shop/pacchetti', (_req, res) => {
    res.setHeader('Cache-Control', 'public, max-age=300');
    res.json({
      currency: 'eur',
      pacchetti: Object.entries(CREDIT_PACKS)
        .filter(([id]) => id !== 'package_2500')
        .map(([id, p]) => ({ id, credits: p.credits, cents: p.cents })),
    });
  });

  // --- IN-MEMORY RATE LIMITER MIDDLEWARE (SECURITY HARDENING) ---
  const ipLimits = new Map<string, { count: number; resetTime: number }>();
  const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
  const MAX_REQUESTS_PER_WINDOW = 100; // Aumentato per gestire la navigazione fluida sulla mappa

  function rateLimiter(req: any, res: any, next: any) {
    // Chiave su req.ip (derivato da Express con `trust proxy`), NON sull'header
    // x-forwarded-for grezzo: quest'ultimo è arbitrario lato client e permetteva
    // di azzerare il contatore a ogni richiesta. Resta un limite di cortesia
    // (in-memory, si resetta a ogni cold start): non è un controllo di sicurezza.
    const ip = req.ip || req.socket?.remoteAddress || "unknown";
    const now = Date.now();
    
    const limitData = ipLimits.get(ip);
    if (!limitData || now > limitData.resetTime) {
      ipLimits.set(ip, { count: 1, resetTime: now + RATE_LIMIT_WINDOW });
      return next();
    }
    
    if (limitData.count >= MAX_REQUESTS_PER_WINDOW) {
      console.warn(`[Rate Limiter] Blocked request from IP ${ip} (Too Many Requests)`);
      return res.status(429).json({ error: "Too many requests. Please try again later." });
    }
    
    limitData.count++;
    next();
  }

  // --- Auth helpers (dichiarazioni hoisted: usabili anche dalle route
  //     registrate PRIMA di verifyAdminToken/const più in basso) ---
  // Verifica un Bearer utente valido SENZA richiedere is_admin.
  // Ritorna lo user id oppure null. Per route che devono solo garantire
  // che il chiamante sia autenticato.
  async function verifyUserToken(req: any): Promise<string | null> {
    const authHeader = String(req.headers.authorization || '');
    if (!authHeader.startsWith('Bearer ')) return null;
    try {
      const userRes = await axios.get(`${supabaseUrl}/auth/v1/user`, {
        headers: { apikey: supabaseServiceKey, Authorization: authHeader }
      });
      return userRes.data?.id || null;
    } catch {
      return null;
    }
  }

  // ── AUTH OBBLIGATORIA + RATE LIMIT PERSISTENTE (audit pre-release SEC-01, 28/08/2026)
  // requireAuth: middleware di rotta. Bearer utente Supabase valido oppure
  // 401 { error: 'auth_required' }; in caso positivo mette req.userId. Va
  // davanti a OGNI rotta che chiama un LLM (callUniversalAi) o un provider
  // TTS a nostre spese: prima molte di queste erano generabili gratis e
  // senza login via curl, col solo rateLimiter in memoria come freno.
  // Bypass per gli script di arricchimento di sfondo (28/08/2026, scratch/*):
  // un header statico confrontato con SCRIPT_SHARED_SECRET, mai mandato dal
  // client web/nativo. Senza, ogni script di sfondo prende sempre 401 non
  // avendo un utente loggato dietro — è quello che ha fermato l'arricchimento
  // natura in corso lo stesso giorno di questo commit.
  const SCRIPT_SHARED_SECRET = process.env.SCRIPT_SHARED_SECRET;
  async function requireAuth(req: any, res: any, next: any) {
    if (SCRIPT_SHARED_SECRET && req.headers['x-script-secret'] === SCRIPT_SHARED_SECRET) {
      req.userId = 'background-script';
      return next();
    }
    let uid: string | null = null;
    try { uid = await verifyUserToken(req); } catch { uid = null; }
    if (!uid) return res.status(401).json({ error: 'auth_required' });
    req.userId = uid;
    next();
  }

  // Rate limit PERSISTENTE su Supabase (tabella api_rate_limits + RPC
  // rate_limit_hit, vedi supabase/migrations/20260828120000_rate_limits.sql).
  // Il rateLimiter in memoria resta come PRIMO filtro (gratis, immediato) ma
  // si azzera a ogni cold start serverless: qui il contatore sopravvive.
  // api_cache NON è adatta: nessuna scadenza, un contatore per minuto
  // lascerebbe righe per sempre e l'incremento leggi-poi-scrivi non è
  // atomico. La RPC fa upsert+incremento in una sola istruzione.
  // Chiave: utente autenticato (req.userId, messo da requireAuth) oppure
  // IP; finestra = minuto corrente. FAIL-OPEN: se la RPC/tabella non esiste
  // ancora o Supabase non risponde, la richiesta passa e si logga UNA volta.
  const RL_COSTOSE_PER_MINUTO = 60;
  let rlFailOpenLoggato = false;
  async function conteggioRateLimitPersistente(chiave: string, finestraSec = 120): Promise<number | null> {
    try {
      const r = await axios.post(
        `${supabaseUrl}/rest/v1/rpc/rate_limit_hit`,
        { p_key: chiave, p_window_seconds: finestraSec },
        { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json' }, timeout: 2500 }
      );
      const n = Number(r.data);
      return Number.isFinite(n) ? n : null;
    } catch (e: any) {
      if (!rlFailOpenLoggato) {
        rlFailOpenLoggato = true;
        console.warn('[rate-limit] RPC rate_limit_hit non disponibile (fail-open):', e?.response?.status || e?.message,
          '— applicare supabase/migrations/20260828120000_rate_limits.sql');
      }
      return null;
    }
  }
  /**
   * Ritorna i secondi di attesa se la richiesta supera il tetto, altrimenti
   * null. Usabile inline nelle rotte che verificano il token a metà handler
   * (es. /api/tts/smart, dove il colpo di cache resta aperto).
   */
  async function limiteCostosoSuperato(req: any, maxPerMinuto = RL_COSTOSE_PER_MINUTO): Promise<number | null> {
    const chi = req.userId ? `u_${req.userId}` : `ip_${req.ip || req.socket?.remoteAddress || 'unknown'}`;
    const adesso = Date.now();
    const minuto = Math.floor(adesso / 60000);
    const n = await conteggioRateLimitPersistente(`rl_${chi}_${minuto}`, 120);
    if (n !== null && n > maxPerMinuto) {
      console.warn(`[rate-limit] ${chi} oltre ${maxPerMinuto}/min su ${req.method} ${req.path} (${n})`);
      return Math.max(1, 60 - Math.floor((adesso / 1000) % 60));
    }
    return null;
  }
  function rateLimitCostoso(maxPerMinuto = RL_COSTOSE_PER_MINUTO) {
    return async (req: any, res: any, next: any) => {
      // (31/08/2026) Gli script di sfondo (x-script-secret) condividono UN
      // solo utente: col tetto normale 60/min l'arricchitore gemme da solo
      // lo saturava e ogni altro script prendeva 429. Per loro il tetto e'
      // piu' largo ma esiste comunque: protegge il DB, non il portafoglio.
      const max = req.userId === 'background-script' ? Math.max(maxPerMinuto, 240) : maxPerMinuto;
      const attesa = await limiteCostosoSuperato(req, max);
      if (attesa !== null) {
        res.setHeader('Retry-After', String(attesa));
        return res.status(429).json({ error: 'rate_limited', retry_after_seconds: attesa });
      }
      next();
    };
  }
  // Catena standard per le rotte costose (LLM/TTS): login + tetto per utente.
  // Il rateLimiter in memoria (per IP) va messo per primo dalla rotta.
  const guardiaCostosa = [requireAuth, rateLimitCostoso()];

  /**
   * Cancello per il ramo "cache miss" delle rotte CACHE-FIRST che oggi sono
   * pubbliche (catalogo stagionale, traduzioni, mini-guide città, TTS…): il
   * colpo di cache non costa nulla e resta aperto; la GENERAZIONE (LLM/TTS
   * a nostre spese) richiede un Bearer valido e passa dal tetto persistente.
   * Ritorna true se si può generare; altrimenti ha GIÀ risposto 401/429.
   */
  async function cancelloGenerazione(req: any, res: any): Promise<boolean> {
    let uid: string | null = null;
    try { uid = await verifyUserToken(req); } catch { uid = null; }
    if (!uid) { res.status(401).json({ error: 'auth_required' }); return false; }
    req.userId = uid;
    const attesa = await limiteCostosoSuperato(req);
    if (attesa !== null) {
      res.setHeader('Retry-After', String(attesa));
      res.status(429).json({ error: 'rate_limited', retry_after_seconds: attesa });
      return false;
    }
    return true;
  }
  /** Come cancelloGenerazione ma SENZA rispondere: la rotta degrada da sé. */
  async function puoGenerare(req: any): Promise<boolean> {
    let uid: string | null = null;
    try { uid = await verifyUserToken(req); } catch { uid = null; }
    if (!uid) return false;
    req.userId = uid;
    return (await limiteCostosoSuperato(req)) === null;
  }

  /**
   * Day Pass attivo (tabella user_passes, migration 20260806120000_day_pass):
   * non scaduto e con guide residue. Il contatore guides_used lo riconcilia
   * il client (prefs native ⇄ server), qui si legge soltanto.
   */
  async function haDayPassAttivo(userId: string): Promise<boolean> {
    try {
      const r = await axios.get(
        `${supabaseUrl}/rest/v1/user_passes?user_id=eq.${encodeURIComponent(userId)}&expires_at=gt.${encodeURIComponent(new Date().toISOString())}&select=guides_used,guides_cap&order=expires_at.desc&limit=1`,
        { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }, timeout: 4000 }
      );
      const p = r.data?.[0];
      return !!p && Number(p.guides_used || 0) < Number(p.guides_cap || 0);
    } catch { return false; }
  }

  /**
   * POSSESSO PERMANENTE DI UN'AUDIOGUIDA (29/08/2026).
   *
   * Regola del committente: «quando l'utente acquista un'audioguida, non la
   * paga mai piu', e' sua». Fino a ieri il diritto scadeva dopo 24 ore
   * (chiave `audiocharge_*` in api_cache) e il POI si ripagava il giorno
   * dopo. Il registro vero e' `user_poi_purchases` (migration
   * 20260829090000): scrivibile SOLO da qui col service role, quindi non
   * falsificabile dal client come lo era `user_listening_history`.
   *
   * Il possesso vale per il POI in TUTTE le lingue e con tutti i registri:
   * la chiave e' (user_id, poi_id), senza lingua.
   *
   * FAIL-SAFE VERSO L'UTENTE: se la tabella non esiste ancora (migration non
   * applicata) o la lettura fallisce, si ripiega sulla vecchia chiave
   * `audiocharge_*` SENZA la finestra dei 30 giorni... anzi, senza finestra
   * affatto: in dubbio non si fa ripagare un cliente.
   */
  async function possiedeIlPoi(userId: string, poiId: string): Promise<boolean> {
    const uid = pgSafe(userId), pid = pgSafe(poiId);
    if (!uid || !pid) return false;
    try {
      const r = await axios.get(
        `${supabaseUrl}/rest/v1/user_poi_purchases?user_id=eq.${uid}&poi_id=eq.${pid}&select=poi_id&limit=1`,
        { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }, timeout: 4000 }
      );
      return Array.isArray(r.data) && r.data.length > 0;
    } catch (e: any) {
      // 404/42P01 = tabella assente: lo dice una volta e passa al ripiego.
      if (!(possiedeIlPoi as any)._avvisato) {
        (possiedeIlPoi as any)._avvisato = true;
        console.warn('[possesso] user_poi_purchases non leggibile, ripiego su audiocharge_*:', e?.message);
      }
      return false;
    }
  }

  /**
   * Registra il possesso dopo un addebito riuscito. Ritorna false solo se la
   * scrittura fallisce per un motivo diverso dalla tabella mancante: il
   * chiamante in quel caso rimborsa, perche' addebitare senza consegnare il
   * possesso significherebbe far ripagare lo stesso POI domani.
   */
  async function registraPossesso(userId: string, poiId: string, cost: number, source = 'crediti'): Promise<boolean> {
    try {
      await axios.post(
        `${supabaseUrl}/rest/v1/user_poi_purchases`,
        { user_id: userId, poi_id: String(poiId), source, cost: Math.max(0, Math.round(cost || 0)) },
        { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json', Prefer: 'resolution=ignore-duplicates,return=minimal' }, timeout: 5000 }
      );
      return true;
    } catch (e: any) {
      const st = e?.response?.status;
      const msg = String(e?.response?.data?.message || e?.message || '');
      // Tabella non ancora creata: non si blocca l'ascolto gia' pagato — resta
      // la chiave audiocharge_* come rete di sicurezza.
      if (st === 404 || /relation .* does not exist|42P01/i.test(msg)) {
        console.warn('[possesso] user_poi_purchases assente: applicare la migration 20260829090000');
        return true;
      }
      console.error('[possesso] scrittura fallita:', msg);
      return false;
    }
  }

  /**
   * Annulla il possesso: si usa SOLO quando si rimborsa un addebito appena
   * fatto perche' la guida non e' stata consegnata. Non e' una revoca — un
   * acquisto riuscito non si toglie mai.
   */
  async function annullaPossesso(userId: string, poiId: string): Promise<void> {
    const uid = pgSafe(userId), pid = pgSafe(poiId);
    if (!uid || !pid) return;
    try {
      await axios.delete(
        `${supabaseUrl}/rest/v1/user_poi_purchases?user_id=eq.${uid}&poi_id=eq.${pid}&source=eq.crediti`,
        { headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }, timeout: 5000 }
      );
    } catch { /* best-effort: il rimborso e' gia' avvenuto */ }
  }

  /** Prime `n` frasi di un testo (anteprima gratuita), tetto 400 caratteri. */
  function primeFrasi(testo: any, n = 2): string {
    const t = String(testo || '').replace(/\s+/g, ' ').trim();
    if (!t) return '';
    const frasi = t.split(/(?<=[.!?…])\s+/).filter(Boolean);
    return frasi.slice(0, n).join(' ').slice(0, 400);
  }

  // ── HELPER DI SICUREZZA (audit 22/08/2026) ────────────────────────────────
  // pgSafe: un valore che finisce in un filtro PostgREST (`id=eq.${x}`,
  // `in.(${x})`) deve essere un uuid o un id "semplice", e va comunque
  // URL-encodato: `x` = "1&status=eq.hidden" cambiava il filtro a piacere.
  // Ritorna null se il valore non è accettabile (il chiamante risponde 400).
  function pgSafe(v: any): string | null {
    const s = String(v ?? '').trim();
    if (!s) return null;
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuid.test(s) && !/^[A-Za-z0-9_:.-]{1,80}$/.test(s)) return null;
    return encodeURIComponent(s);
  }
  // safeWikiLang: il sottodominio di wikipedia/wikivoyage viene dal body:
  // "it.evil.com/?" avrebbe mandato la richiesta server-side a un host
  // arbitrario (SSRF). Solo due lettere minuscole, altrimenti 'it'.
  function safeWikiLang(v: any, fallback = 'it'): string {
    const s = String(v ?? '').toLowerCase().trim();
    return /^[a-z]{2}$/.test(s) ? s : fallback;
  }
  // Risposta d'errore generica: il dettaglio (e.message, stack, percorsi
  // interni, URL con chiavi) resta nei log server.
  function rispostaErroreGenerica(res: any, tag: string, e: any, status = 500) {
    console.error(`[${tag}]`, e?.message || e);
    return res.status(status).json({ error: 'internal_error' });
  }

  // Prezzario autorevole server-side per il GATE CREDITI. Prima nessuna rotta
  // costosa (tranne la chat) verificava i crediti: la sequenza consumeCredits
  // → fetch viveva solo nel client, quindi ogni servizio era gratis via cURL.
  // Allineare a src/lib/pricing.ts.
  const SERVER_PRICING: Record<string, number> = {
    premium_guide_daily: 20, audio_guide: 15, itinerary_daily: 10,
    // replace_stop (8) e poi_detail/audio_guide allineati a src/lib/pricing.ts
    // (PRICING_LIST): il gate crediti server-side deve usare gli STESSI valori.
    replace_stop: 8,
    photo_search: 5, poi_detail: 5, podcast_daily: 15,
    // WIP Day Pass: 24 ore hands-free, 40 audioguide. Mancava (03/09/2026):
    // finche' l'attivazione stava nel client il server non doveva conoscerne
    // il prezzo, ma ora l'addebito lo fa lui e senza questa voce `prezzoDi`
    // avrebbe restituito `undefined`. Stesso valore di PRICING_LIST.day_pass.
    day_pass: 200,
    // Pass Museo: riconoscimenti Vision per MUSEUM_PASS_HOURS ore (indoor).
    // 100 crediti (~1€) per 40 audioguide (MUSEUM_PASS_MAX_SCANS), inquadrando
    // le opere che si vogliono: break-even col costo AI (~1,2 cent/scansione
    // gpt-4o). 150 con la VISITA GUIDATA: stesse 40 audioguide più il percorso
    // interno del museo (sale, ordine, opere da non perdere), che costa una
    // generazione in più e vale come servizio a sé (10/09/2026).
    museum_pass: 100,
    museum_pass_tour: 150,
    // NUOVO (hardening ago 2026) — /api/regenerate: src/lib/pricing.ts
    // (PRICING_LIST) NON ha una voce dedicata per questa rotta. Il client
    // oggi addebita `audio_guide` A PARTE (nel modale crediti) PRIMA di
    // chiamare /api/regenerate per la narrazione principale, e non addebita
    // affatto i livelli "Chiedi di più" (audioguideService.askMore) né le
    // domande fatte mentre si ascolta (PoiAudioPlayer "Chiedi mentre
    // ascolti"): la rotta era quindi generabile gratis e senza login via
    // curl. Costo provvisorio allineato a poi_detail/photo_search — DA
    // RIVEDERE lato prodotto (valutare se unificarlo a audio_guide o
    // renderlo gratuito per chi ha già pagato la narrazione del POI).
    chiedi_di_piu: 5,
    // /api/itinerary/extend: "Aggiungi un giorno"/"Aggiungi una tappa
    // vicina" su un itinerario ESISTENTE. Prezzo pieno addebitato subito;
    // se il giorno viene servito dalla cache della Libreria (già generato e
    // verificato) si rimborsa la metà a fine richiesta — vedi la rotta.
    extend_itinerary_day: 12,
  };

  // ── LISTINO EFFETTIVO (override da pannello, senza deploy) ─────────────
  // SERVER_PRICING resta la verità cablata e il pavimento di sicurezza; il
  // pannello admin può sovrascrivere singole voci salvandole in api_cache
  // ('pricing_config'). Stessa forma di isFeatureFlagOn: cache in memoria
  // 60 secondi (il serverless ricrea il processo di continuo, quindi la
  // finestra di disallineamento è cortissima) e FAIL-SAFE — se il DB non
  // risponde o la voce manca si usa il valore cablato. Un prezzo non deve
  // MAI diventare 0 per un timeout di Supabase.
  let serverPricingCache: { at: number; overrides: Record<string, number>; updatedAt: string | null } | null = null;
  async function leggiOverridePrezzi(): Promise<{ overrides: Record<string, number>; updatedAt: string | null }> {
    if (serverPricingCache && Date.now() - serverPricingCache.at < 60000) {
      return { overrides: serverPricingCache.overrides, updatedAt: serverPricingCache.updatedAt };
    }
    try {
      const r = await axios.get(`${supabaseUrl}/rest/v1/api_cache?cache_key=eq.pricing_config&select=text_content`, {
        headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }, timeout: 3000
      });
      // text_content torna come oggetto (jsonb) o come stringa JSON a seconda
      // di come è stata scritta la riga: si accettano entrambe le forme.
      let payload: any = r.data?.[0]?.text_content ?? null;
      if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch { payload = null; } }
      const overrides: Record<string, number> = {};
      for (const [k, v] of Object.entries(payload?.overrides || {})) {
        // Whitelist: solo voci che esistono davvero nel listino cablato.
        if (k in SERVER_PRICING && Number.isFinite(Number(v))) overrides[k] = Math.trunc(Number(v));
      }
      serverPricingCache = { at: Date.now(), overrides, updatedAt: payload?.updated_at || null };
    } catch {
      // Fail-safe: DB muto = listino cablato. L'errore NON viene messo in
      // cache, così il tentativo successivo riprova subito.
      return { overrides: {}, updatedAt: null };
    }
    return { overrides: serverPricingCache.overrides, updatedAt: serverPricingCache.updatedAt };
  }

  /** Listino effettivo = SERVER_PRICING + override attivi. */
  async function listinoPrezzi(): Promise<Record<string, number>> {
    const { overrides } = await leggiOverridePrezzi();
    return { ...SERVER_PRICING, ...overrides };
  }

  /** Prezzo in crediti di una feature. Fail-safe sul valore cablato. */
  async function prezzoDi(feature: string): Promise<number> {
    const cablato = SERVER_PRICING[feature];
    try {
      const { overrides } = await leggiOverridePrezzi();
      const v = overrides[feature];
      return Number.isFinite(v) ? v : cablato;
    } catch {
      return cablato;
    }
  }

  // Header service-role riusati dagli helper crediti.
  const CREDIT_SVC_HEADERS = { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json' };

  /**
   * Addebito robusto. RPC atomica `consume_credits` (earned-first) preferita;
   * se la RPC non è applicata sul DB si ripiega su una scrittura service-key
   * (che bypassa il trigger anti-escalation su user_profiles). Il trigger
   * blocca ogni scrittura crediti dal client, quindi TUTTI i consumi devono
   * passare da qui. Ritorna 'ok' | 'insufficient' | 'error'.
   */
  async function consumeCreditsServer(userId: string, amount: number, causale?: string): Promise<'ok' | 'insufficient' | 'error'> {
    if (amount <= 0) return 'ok';
    // LA CAUSALE (29/08/2026, collaudo): il libro mastro registrava importo e
    // ora, ma `description` restava NULL su OGNI consumo — davanti a un
    // «perche' mi avete tolto 200 crediti?» si leggeva solo «consume -200».
    // La versione a TRE argomenti della RPC (migration
    // 20260829200000_consume_credits_causale.sql) scrive anche la causale;
    // finche' quella migration non e' applicata la chiamata fallisce e si
    // ripiega su quella a due, esattamente come prima.
    if (causale) {
      try {
        const rpc3 = await axios.post(`${supabaseUrl}/rest/v1/rpc/consume_credits`,
          { p_user_id: userId, p_amount: amount, p_description: causale }, { headers: CREDIT_SVC_HEADERS });
        if (rpc3.data === true) return 'ok';
        if (rpc3.data === false) return 'insufficient';
      } catch { /* migration non applicata → si prova la versione a due */ }
    }
    try {
      const rpc = await axios.post(`${supabaseUrl}/rest/v1/rpc/consume_credits`,
        { p_user_id: userId, p_amount: amount }, { headers: CREDIT_SVC_HEADERS });
      if (rpc.data === true) return 'ok';
      if (rpc.data === false) return 'insufficient';
    } catch { /* RPC assente/errore → fallback */ }
    try {
      const { data: prof } = await axios.get(
        `${supabaseUrl}/rest/v1/user_profiles?id=eq.${userId}&select=earned_credits,purchased_credits`, { headers: CREDIT_SVC_HEADERS });
      let earned = Number(prof?.[0]?.earned_credits) || 0;
      let purchased = Number(prof?.[0]?.purchased_credits) || 0;
      if (earned + purchased < amount) return 'insufficient';
      let rem = amount;
      if (earned >= rem) { earned -= rem; rem = 0; } else { rem -= earned; earned = 0; }
      if (rem > 0) purchased -= rem;
      await axios.patch(`${supabaseUrl}/rest/v1/user_profiles?id=eq.${userId}`,
        { earned_credits: earned, purchased_credits: purchased }, { headers: CREDIT_SVC_HEADERS });
      // Traccia il consumo anche sul percorso di fallback (la RPC consume_credits
      // logga da sé): serve alla guardia anti-conio di /api/credits/refund, che
      // rimborsa solo fino a quanto risulta realmente consumato in credit_transactions.
      await axios.post(`${supabaseUrl}/rest/v1/credit_transactions`,
        { user_id: userId, amount: -amount, type: 'consume', source: 'server', description: causale ? String(causale).slice(0, 200) : null },
        { headers: CREDIT_SVC_HEADERS }).catch(() => {});
      return 'ok';
    } catch { return 'error'; }
  }

  /** Rimborso robusto (RPC atomica o fallback service-key su purchased). */
  async function refundCreditsServer(userId: string, amount: number): Promise<boolean> {
    if (amount <= 0) return true;
    try {
      await axios.post(`${supabaseUrl}/rest/v1/rpc/refund_credits_service`,
        { p_user_id: userId, p_amount: amount }, { headers: CREDIT_SVC_HEADERS });
      return true;
    } catch { /* RPC assente/errore → fallback */ }
    try {
      const { data: prof } = await axios.get(
        `${supabaseUrl}/rest/v1/user_profiles?id=eq.${userId}&select=purchased_credits`, { headers: CREDIT_SVC_HEADERS });
      const purchased = Number(prof?.[0]?.purchased_credits) || 0;
      await axios.patch(`${supabaseUrl}/rest/v1/user_profiles?id=eq.${userId}`,
        { purchased_credits: purchased + amount }, { headers: CREDIT_SVC_HEADERS });
      // Traccia OGNI rimborso (anche quelli server-interni: vision/podcast/guida
      // falliti) così la guardia anti-conio conta correttamente quanto è già
      // stato restituito nella finestra e non si può rimborsare due volte.
      await axios.post(`${supabaseUrl}/rest/v1/credit_transactions`,
        { user_id: userId, amount, type: 'refund', source: 'server' },
        { headers: CREDIT_SVC_HEADERS }).catch(() => {});
      return true;
    } catch { return false; }
  }

  /**
   * Verifica il TOKEN (mai il body) e addebita `feature × units` crediti.
   * Ritorna {userId, cost} o null avendo già inviato la risposta d'errore
   * (401 login, 402 crediti, 500). Il chiamante genera e, in caso di
   * fallimento, rimborsa con refundServer.
   */
  async function chargeOrReject(req: any, res: any, feature: string, units: number = 1): Promise<{ userId: string; cost: number } | null> {
    const userId = await verifyUserToken(req);
    if (!userId) { res.status(401).json({ error: 'login_required' }); return null; }
    // La feature deve esistere nel listino CABLATO (whitelist); il prezzo
    // applicato è invece quello effettivo, override del pannello compresi.
    // Il controllo è su `in SERVER_PRICING` e non su `!unit` perché un
    // override a 0 (feature resa gratuita) è legittimo e non va scambiato
    // per una feature sconosciuta.
    const unit = (feature in SERVER_PRICING) ? await prezzoDi(feature) : undefined;
    if (unit === undefined) { res.status(500).json({ error: 'unknown_feature' }); return null; }
    const cost = unit * Math.max(1, Math.floor(units));
    // La causale nel libro mastro e` il NOME della feature (piu` le unita`,
    // quando sono piu` d'una: «itinerary_daily ×4» si legge, «-40» no).
    const causale = units > 1 ? `${feature} ×${Math.floor(units)}` : feature;
    const outcome = await consumeCreditsServer(userId, cost, causale);
    if (outcome === 'insufficient') { res.status(402).json({ error: 'insufficient_credits', cost }); return null; }
    if (outcome === 'error') { res.status(500).json({ error: 'charge_failed' }); return null; }
    return { userId, cost };
  }

  /** Rimborso server-side (generazione fallita dopo l'addebito). Best-effort. */
  async function refundServer(userId: string, amount: number): Promise<void> {
    const ok = await refundCreditsServer(userId, amount);
    if (!ok) await logSystemError('critical', `Rimborso server-side fallito`, { source: 'chargeOrReject', userId, amount });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // NOTIFICHE (email + push) E GENERAZIONI IN DIFFERITA — 06/09/2026
  //
  // Decisione del committente: chi chiede una guida premium (o un itinerario
  // lungo) non deve restare con lo schermo acceso. La richiesta entra in coda
  // (`generazioni`), il server la porta a termine da solo, la salva
  // nell'Archivio e avvisa con EMAIL (sempre, sia itinerario che guida, con il
  // PDF) e PUSH («🎉 La tua guida è pronta!»). Le push servono anche alle
  // comunicazioni col cliente (pannello admin «Notifiche»).
  //
  // Email: Resend via REST (RESEND_API_KEY, RESEND_FROM). Nessun SMTP: prima
  // di oggi l'app non mandava email proprie.
  // Push: Firebase Cloud Messaging HTTP v1, autenticazione con il service
  // account (FIREBASE_SERVICE_ACCOUNT = JSON) firmando il JWT con crypto di
  // Node: niente firebase-admin (pesa 30 MB nella function).
  // Senza chiavi configurate ogni canale si limita a registrare «non
  // configurato» in `notifiche.esito`: mai un errore per l'utente.
  // ═══════════════════════════════════════════════════════════════════════════
  const SB_HDR = () => ({ apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json' });

  /** Email dell'account (auth.users), letta con la service role. */
  async function emailUtente(userId: string): Promise<string | null> {
    try {
      const r = await axios.get(`${supabaseUrl}/auth/v1/admin/users/${encodeURIComponent(userId)}`, { headers: SB_HDR(), timeout: 8000 });
      return r.data?.email || null;
    } catch { return null; }
  }

  /** Lingua dell'utente: dal profilo se c'e', altrimenti quella passata. */
  function linguaNotifica(l: any): string {
    const s = String(l || 'IT').toUpperCase();
    return ['IT', 'EN', 'FR', 'ES', 'DE', 'RU', 'ZH'].includes(s) ? s : 'IT';
  }

  /**
   * Invio email con Resend. `allegati` = [{ filename, content: Buffer|base64 }].
   * Ritorna { ok, errore? }. Destinatari validati e al massimo 6 (account + 5).
   */
  async function inviaEmail(a: { a: string[]; oggetto: string; html: string; testo?: string; allegati?: Array<{ filename: string; content: Buffer | string }> }): Promise<{ ok: boolean; errore?: string }> {
    const validi = Array.from(new Set(a.a.map(x => String(x || '').trim().toLowerCase()).filter(x => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(x)))).slice(0, 6);
    if (!validi.length) return { ok: false, errore: 'nessun_destinatario' };
    // BREVO prima di tutto (06/09/2026): e' il provider gia' in uso per le
    // email di Supabase Auth (smtp-relay.brevo.com, noreply@wip.guide), col
    // dominio gia' verificato. API transazionale, allegati in base64.
    const brevo = process.env.BREVO_API_KEY;
    if (brevo) {
      try {
        const mitt = (process.env.EMAIL_FROM || 'WIP - World in Pocket <noreply@wip.guide>').match(/^(.*?)\s*<([^>]+)>$/);
        const r = await axios.post('https://api.brevo.com/v3/smtp/email', {
          sender: { name: mitt ? mitt[1].trim() : 'WIP', email: mitt ? mitt[2] : 'noreply@wip.guide' },
          to: validi.map(email => ({ email })),
          subject: a.oggetto,
          htmlContent: a.html,
          textContent: a.testo,
          attachment: (a.allegati || []).length ? (a.allegati || []).map(x => ({ name: x.filename, content: Buffer.isBuffer(x.content) ? x.content.toString('base64') : x.content })) : undefined,
        }, { headers: { 'api-key': brevo, 'Content-Type': 'application/json', Accept: 'application/json' }, timeout: 20000 });
        return r.status < 300 ? { ok: true } : { ok: false, errore: `HTTP ${r.status}` };
      } catch (e: any) {
        return { ok: false, errore: e?.response?.data?.message || e?.message || 'errore' };
      }
    }
    const key = process.env.RESEND_API_KEY;
    if (!key) return { ok: false, errore: 'non_configurato' };
    try {
      const r = await axios.post('https://api.resend.com/emails', {
        from: process.env.RESEND_FROM || process.env.EMAIL_FROM || 'WIP - World in Pocket <noreply@wip.guide>',
        to: validi,
        subject: a.oggetto,
        html: a.html,
        text: a.testo,
        attachments: (a.allegati || []).map(x => ({ filename: x.filename, content: Buffer.isBuffer(x.content) ? x.content.toString('base64') : x.content })),
      }, { headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' }, timeout: 20000 });
      return r.status < 300 ? { ok: true } : { ok: false, errore: `HTTP ${r.status}` };
    } catch (e: any) {
      return { ok: false, errore: e?.response?.data?.message || e?.message || 'errore' };
    }
  }

  // ── FCM v1: token OAuth dal service account, in cache fino a scadenza ────
  let fcmToken: { valore: string; scade: number } | null = null;
  function fcmAccount(): any | null {
    try { const j = process.env.FIREBASE_SERVICE_ACCOUNT; return j ? JSON.parse(j) : null; } catch { return null; }
  }
  async function fcmAccessToken(): Promise<string | null> {
    const sa = fcmAccount();
    if (!sa?.client_email || !sa?.private_key) return null;
    if (fcmToken && fcmToken.scade > Date.now() + 60000) return fcmToken.valore;
    const now = Math.floor(Date.now() / 1000);
    const b64 = (o: any) => Buffer.from(JSON.stringify(o)).toString('base64url');
    const head = b64({ alg: 'RS256', typ: 'JWT' });
    const claim = b64({ iss: sa.client_email, scope: 'https://www.googleapis.com/auth/firebase.messaging', aud: 'https://oauth2.googleapis.com/token', iat: now, exp: now + 3600 });
    const firma = crypto.sign('RSA-SHA256', Buffer.from(`${head}.${claim}`), sa.private_key).toString('base64url');
    try {
      const r = await axios.post('https://oauth2.googleapis.com/token',
        new URLSearchParams({ grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion: `${head}.${claim}.${firma}` }).toString(),
        { headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, timeout: 10000 });
      fcmToken = { valore: r.data.access_token, scade: Date.now() + (Number(r.data.expires_in) || 3600) * 1000 };
      return fcmToken.valore;
    } catch (e: any) { console.warn('[push] token FCM fallito:', e?.response?.data?.error_description || e?.message); return null; }
  }

  /**
   * Push a tutti i dispositivi dell'utente. Rispetta le preferenze del
   * profilo (push_servizio / push_promo); i token non piu' validi vengono
   * cancellati. Ritorna quanti invii sono andati a buon fine.
   */
  async function inviaPush(userId: string, n: { titolo: string; corpo: string; dati?: Record<string, string>; tipo?: 'servizio' | 'promo' }): Promise<{ inviate: number; errore?: string }> {
    const sa = fcmAccount();
    if (!sa?.project_id) return { inviate: 0, errore: 'non_configurato' };
    try {
      const prof = await axios.get(`${supabaseUrl}/rest/v1/user_profiles?id=eq.${userId}&select=push_servizio,push_promo`, { headers: SB_HDR(), timeout: 6000 }).catch(() => null);
      const p = prof?.data?.[0] || {};
      if ((n.tipo || 'servizio') === 'promo' ? p.push_promo !== true : p.push_servizio === false) return { inviate: 0, errore: 'preferenza_utente' };
      const disp = await axios.get(`${supabaseUrl}/rest/v1/dispositivi_push?user_id=eq.${userId}&select=id,token`, { headers: SB_HDR(), timeout: 6000 });
      const tokens: Array<{ id: string; token: string }> = disp.data || [];
      if (!tokens.length) return { inviate: 0, errore: 'nessun_dispositivo' };
      const access = await fcmAccessToken();
      if (!access) return { inviate: 0, errore: 'token_fcm' };
      let inviate = 0;
      for (const d of tokens) {
        try {
          await axios.post(`https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`, {
            message: {
              token: d.token,
              notification: { title: n.titolo, body: n.corpo },
              data: Object.fromEntries(Object.entries(n.dati || {}).map(([k, v]) => [k, String(v)])),
              android: { priority: 'high', notification: { channel_id: 'wip_servizio', sound: 'default' } },
              apns: { payload: { aps: { sound: 'default', badge: 1 } } },
            }
          }, { headers: { Authorization: `Bearer ${access}`, 'Content-Type': 'application/json' }, timeout: 10000 });
          inviate++;
        } catch (e: any) {
          const codice = e?.response?.data?.error?.details?.[0]?.errorCode || e?.response?.data?.error?.status;
          if (codice === 'UNREGISTERED' || codice === 'NOT_FOUND' || e?.response?.status === 404) {
            await axios.delete(`${supabaseUrl}/rest/v1/dispositivi_push?id=eq.${d.id}`, { headers: SB_HDR(), timeout: 6000 }).catch(() => {});
          } else console.warn('[push] invio fallito:', codice || e?.message);
        }
      }
      return { inviate };
    } catch (e: any) { return { inviate: 0, errore: e?.message }; }
  }

  /** Riga nel registro `notifiche` (inbox dell'app + registro admin). */
  async function registraNotifica(userId: string, n: { titolo: string; corpo: string; dati?: any; tipo?: 'servizio' | 'promo'; canali: string[]; esito: any; inviata_da?: string | null }): Promise<void> {
    try {
      await axios.post(`${supabaseUrl}/rest/v1/notifiche`, {
        user_id: userId, tipo: n.tipo || 'servizio', titolo: n.titolo, corpo: n.corpo,
        dati: n.dati || {}, canali: n.canali, esito: n.esito, inviata_da: n.inviata_da || null,
      }, { headers: { ...SB_HDR(), Prefer: 'return=minimal' }, timeout: 8000 });
    } catch (e: any) { console.warn('[notifiche] registro fallito:', e?.message); }
  }

  /**
   * Notifica completa (push + email opzionale + registro) a un utente.
   * `email` = { oggetto, html, testo?, allegati?, extra?: string[] } oppure
   * assente per la sola push.
   */
  async function notificaUtente(userId: string, n: { titolo: string; corpo: string; dati?: Record<string, string>; tipo?: 'servizio' | 'promo'; inviata_da?: string | null; email?: { oggetto: string; html: string; testo?: string; allegati?: any[]; extra?: string[] } }): Promise<{ push: any; email: any }> {
    const esito: any = {};
    const canali: string[] = ['inapp'];
    esito.push = await inviaPush(userId, { titolo: n.titolo, corpo: n.corpo, dati: n.dati, tipo: n.tipo });
    if (esito.push.inviate > 0) canali.push('push');
    if (n.email) {
      const principale = await emailUtente(userId);
      const dest = [principale, ...(n.email.extra || [])].filter(Boolean) as string[];
      esito.email = await inviaEmail({ a: dest, oggetto: n.email.oggetto, html: n.email.html, testo: n.email.testo, allegati: n.email.allegati });
      if (esito.email.ok) canali.push('email');
    }
    await registraNotifica(userId, { titolo: n.titolo, corpo: n.corpo, dati: n.dati, tipo: n.tipo, canali, esito, inviata_da: n.inviata_da });
    return esito;
  }

  // ── Coda `generazioni` ────────────────────────────────────────────────────
  async function generazioneAggiorna(id: string, campi: any): Promise<void> {
    await axios.patch(`${supabaseUrl}/rest/v1/generazioni?id=eq.${encodeURIComponent(id)}`, { ...campi, updated_at: new Date().toISOString() },
      { headers: { ...SB_HDR(), Prefer: 'return=minimal' }, timeout: 8000 }).catch((e: any) => console.warn('[generazioni] aggiornamento fallito:', e?.message));
  }
  async function generazioneLeggi(id: string): Promise<any | null> {
    try {
      const r = await axios.get(`${supabaseUrl}/rest/v1/generazioni?id=eq.${encodeURIComponent(id)}&select=*&limit=1`, { headers: SB_HDR(), timeout: 8000 });
      return r.data?.[0] || null;
    } catch { return null; }
  }

  /** Testi della notifica «pronta» nella lingua dell'utente. */
  function testiPronta(tipo: string, lingua: string, titolo: string): { titolo: string; corpo: string; oggetto: string; intro: string; apri: string } {
    const L = linguaNotifica(lingua);
    const guida = tipo === 'guida';
    const T: Record<string, any> = {
      IT: { titolo: guida ? '🎉 La tua guida è pronta!' : '🎉 Il tuo itinerario è pronto!', corpo: `${titolo} — aprilo nel tuo Archivio.`, oggetto: guida ? `La tua Guida d'Autore è pronta: ${titolo}` : `Il tuo itinerario è pronto: ${titolo}`, intro: guida ? 'La tua Guida d\'Autore è pronta: la trovi nell\'Archivio dell\'app e in allegato come PDF.' : 'Il tuo itinerario è pronto: lo trovi nell\'Archivio dell\'app e in allegato come PDF.', apri: 'Apri in WIP' },
      EN: { titolo: guida ? '🎉 Your guide is ready!' : '🎉 Your itinerary is ready!', corpo: `${titolo} — open it in your Archive.`, oggetto: guida ? `Your Author's Guide is ready: ${titolo}` : `Your itinerary is ready: ${titolo}`, intro: guida ? 'Your Author\'s Guide is ready: find it in the app Archive and attached as a PDF.' : 'Your itinerary is ready: find it in the app Archive and attached as a PDF.', apri: 'Open in WIP' },
      FR: { titolo: guida ? '🎉 Votre guide est prêt !' : '🎉 Votre itinéraire est prêt !', corpo: `${titolo} — ouvrez-le dans vos Archives.`, oggetto: guida ? `Votre guide est prêt : ${titolo}` : `Votre itinéraire est prêt : ${titolo}`, intro: 'C\'est prêt : retrouvez-le dans les Archives de l\'app et en pièce jointe (PDF).', apri: 'Ouvrir dans WIP' },
      ES: { titolo: guida ? '🎉 ¡Tu guía está lista!' : '🎉 ¡Tu itinerario está listo!', corpo: `${titolo} — ábrelo en tu Archivo.`, oggetto: guida ? `Tu guía está lista: ${titolo}` : `Tu itinerario está listo: ${titolo}`, intro: 'Está listo: lo encuentras en el Archivo de la app y adjunto en PDF.', apri: 'Abrir en WIP' },
      DE: { titolo: guida ? '🎉 Dein Guide ist fertig!' : '🎉 Deine Reiseroute ist fertig!', corpo: `${titolo} — im Archiv öffnen.`, oggetto: guida ? `Dein Guide ist fertig: ${titolo}` : `Deine Reiseroute ist fertig: ${titolo}`, intro: 'Fertig: du findest es im Archiv der App und als PDF im Anhang.', apri: 'In WIP öffnen' },
      RU: { titolo: guida ? '🎉 Ваш гид готов!' : '🎉 Ваш маршрут готов!', corpo: `${titolo} — откройте в Архиве.`, oggetto: guida ? `Ваш гид готов: ${titolo}` : `Ваш маршрут готов: ${titolo}`, intro: 'Готово: смотрите в Архиве приложения и во вложении (PDF).', apri: 'Открыть в WIP' },
      ZH: { titolo: guida ? '🎉 您的指南已准备好！' : '🎉 您的行程已准备好！', corpo: `${titolo} — 在“档案”中打开。`, oggetto: guida ? `您的指南已准备好：${titolo}` : `您的行程已准备好：${titolo}`, intro: '已准备好：请在应用的“档案”中查看，PDF 见附件。', apri: '在 WIP 中打开' },
    };
    return T[L] || T.IT;
  }

  function htmlEmailPronta(t: { intro: string; apri: string }, titolo: string, link: string): string {
    const esc = (s: string) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c] as string));
    return `<div style="font-family:Helvetica,Arial,sans-serif;max-width:560px;margin:0 auto;color:#1f2937">
  <div style="background:#1e3a8a;color:#fff;padding:20px 24px;border-radius:12px 12px 0 0"><div style="font-size:12px;letter-spacing:.2em;opacity:.8">WIP · WORLD IN POCKET</div><div style="font-size:20px;font-weight:700;margin-top:6px">${esc(titolo)}</div></div>
  <div style="padding:22px 24px;border:1px solid #e5e7eb;border-top:0;border-radius:0 0 12px 12px">
    <p style="font-size:15px;line-height:1.5">${esc(t.intro)}</p>
    <p style="margin:22px 0"><a href="${esc(link)}" style="background:#e8611a;color:#fff;text-decoration:none;padding:12px 20px;border-radius:999px;font-weight:700">${esc(t.apri)}</a></p>
    <p style="font-size:12px;color:#6b7280">wip.guide</p>
  </div></div>`;
  }

  /**
   * Chiusura di una generazione riuscita: stato `pronta`, push + email (con
   * PDF se disponibile) + registro. Idempotente: se gia' notificata, esce.
   */
  async function generazionePronta(jobId: string, risultatoId: string, titolo: string, pdf?: { filename: string; content: Buffer } | null): Promise<void> {
    const job = await generazioneLeggi(jobId);
    if (!job || job.notificata_at) return;
    await generazioneAggiorna(jobId, { stato: 'pronta', risultato_id: risultatoId, titolo: titolo || job.titolo, pronta_at: new Date().toISOString(), errore: null });
    const t = testiPronta(job.tipo, job.lingua, titolo || job.titolo || '');
    const link = `https://www.wip.guide/?archivio=${job.tipo === 'guida' ? 'guide' : 'itinerari'}`;
    await notificaUtente(job.user_id, {
      titolo: t.titolo, corpo: t.corpo, tipo: 'servizio',
      dati: { azione: 'archivio', tipo: job.tipo, id: risultatoId, generazione: jobId },
      email: { oggetto: t.oggetto, html: htmlEmailPronta(t, titolo || job.titolo || '', link), testo: `${t.intro}\n${link}`, allegati: pdf ? [pdf] : [], extra: Array.isArray(job.email_extra) ? job.email_extra : [] },
    });
    await generazioneAggiorna(jobId, { notificata_at: new Date().toISOString() });
  }

  /** Fallimento definitivo: stato `fallita`, rimborso, avviso. */
  async function generazioneFallita(jobId: string, errore: string): Promise<void> {
    const job = await generazioneLeggi(jobId);
    if (!job || job.stato === 'pronta' || job.stato === 'fallita') return;
    await generazioneAggiorna(jobId, { stato: 'fallita', errore: String(errore || 'errore').slice(0, 500) });
    if (job.crediti > 0) await refundServer(job.user_id, job.crediti);
    const L = linguaNotifica(job.lingua);
    const testi: Record<string, [string, string]> = {
      IT: ['Generazione non riuscita', `Non siamo riusciti a preparare «${job.titolo || ''}». I crediti ti sono stati restituiti: riprova quando vuoi.`],
      EN: ['Generation failed', `We could not prepare "${job.titolo || ''}". Your credits have been refunded: try again anytime.`],
    };
    const [ti, co] = testi[L] || testi.EN;
    await notificaUtente(job.user_id, { titolo: ti, corpo: co, tipo: 'servizio', dati: { azione: 'archivio', generazione: jobId } });
  }

  /**
   * Avvio del lavoro: chiamata INTERNA alla rotta che sa gia' generare (la
   * guida: /api/premium-guide/generate; l'itinerario:
   * /api/groq/itinerary-stream) con il segreto di infrastruttura e il
   * jobId. Ogni rotta gira nella SUA invocazione (300 s su Vercel), salva il
   * risultato e chiude il lavoro. Qui non si aspetta la risposta: la
   * richiesta parte e si torna subito all'utente; il cron riprova i lavori
   * rimasti a meta'.
   */
  function baseInterna(): string {
    if (process.env.INTERNAL_BASE_URL) return process.env.INTERNAL_BASE_URL;
    if (process.env.VERCEL) return 'https://www.wip.guide';
    return `http://localhost:${process.env.PORT || 3000}`;
  }
  async function generazioneAvvia(job: any): Promise<void> {
    if (!SCRIPT_SHARED_SECRET) { await generazioneFallita(job.id, 'SCRIPT_SHARED_SECRET mancante: il lavoratore non puo\' autenticarsi'); return; }
    await generazioneAggiorna(job.id, { stato: 'in_corso', avviata_at: new Date().toISOString(), tentativi: (Number(job.tentativi) || 0) + 1 });
    const percorso = job.tipo === 'guida' ? '/api/premium-guide/generate' : '/api/groq/itinerary-stream';
    const body = { ...(job.parametri || {}), userId: job.user_id, jobId: job.id, language: job.lingua };
    const p = axios.post(`${baseInterna()}${percorso}`, body, {
      headers: { 'Content-Type': 'application/json', 'x-script-secret': SCRIPT_SHARED_SECRET, 'x-job-id': job.id },
      timeout: 290000, maxContentLength: Infinity, maxBodyLength: Infinity, responseType: 'text',
    }).then(() => undefined).catch((e: any) => console.warn(`[generazioni] lavoro ${job.id} (${job.tipo}):`, e?.code || e?.message));
    // Su Vercel la function viene congelata alla risposta: waitUntil la
    // tiene viva finche' il lavoro non ha ricevuto risposta (o scade).
    try {
      const vf = await import('@vercel/functions').catch(() => null as any);
      if (vf?.waitUntil) vf.waitUntil(p); else void p;
    } catch { void p; }
  }

  /** PDF della guida per l'allegato email (null se non realizzabile). */
  async function pdfGuidaPerEmail(content: any, mediaManifest: any, language: any): Promise<{ filename: string; content: Buffer } | null> {
    try {
      const { pdfGuidaServer } = await import('./src/lib/pdf/serverPdf.js');
      const buf = await pdfGuidaServer(content, mediaManifest || {}, language);
      if (!buf) return null;
      const nome = String(content?.guida_titolo || 'Guida').replace(/[^\p{L}\p{N} _-]+/gu, '').trim().slice(0, 60) || 'Guida';
      return { filename: `WIP ${nome}.pdf`, content: buf };
    } catch (e: any) { console.warn('[pdf email] guida:', e?.message); return null; }
  }
  /** PDF dell'itinerario per l'allegato email (null se non realizzabile). */
  async function pdfItinerarioPerEmail(plan: any, language: any): Promise<{ filename: string; content: Buffer } | null> {
    try {
      const { pdfItinerarioServer } = await import('./src/lib/pdf/serverPdf.js');
      const buf = await pdfItinerarioServer(plan, language);
      if (!buf) return null;
      const nome = String(plan?.titolo || 'Itinerario').replace(/[^\p{L}\p{N} _-]+/gu, '').trim().slice(0, 60) || 'Itinerario';
      return { filename: `WIP ${nome}.pdf`, content: buf };
    } catch (e: any) { console.warn('[pdf email] itinerario:', e?.message); return null; }
  }

  /**
   * Chi chiama una rotta di generazione PER CONTO di un lavoro in coda: il
   * segreto di infrastruttura + jobId nel body. Ritorna il lavoro (con
   * user_id e crediti gia' addebitati) oppure null se non e' una chiamata
   * interna valida.
   */
  async function lavoroInterno(req: any): Promise<any | null> {
    const jobId = String(req.body?.jobId || req.headers['x-job-id'] || '');
    if (!jobId || !SCRIPT_SHARED_SECRET || req.headers['x-script-secret'] !== SCRIPT_SHARED_SECRET) return null;
    const job = await generazioneLeggi(jobId);
    if (!job || job.stato === 'pronta' || job.stato === 'fallita') return null;
    return job;
  }

  // Come verifyUserToken ma richiede is_admin = true sul profilo.
  async function verifyAdminBearer(req: any): Promise<string | null> {
    const uid = await verifyUserToken(req);
    if (!uid) return null;
    try {
      const profileRes = await axios.get(`${supabaseUrl}/rest/v1/user_profiles?id=eq.${uid}&select=is_admin`, {
        headers: { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}` }
      });
      return profileRes.data?.[0]?.is_admin === true ? uid : null;
    } catch {
      return null;
    }
  }

  // Initialize Gemini with multiple keys support. Prima leggeva solo
  // GEMINI_API_KEY/_2/_3: _1 e _4 erano configurate ma MAI usate (bug trovato
  // 25/08/2026 — sul droplet le 5 variabili erano per giunta la STESSA chiave
