  // (29/08/2026) LA SCHEDA DEL LOCALE (locali_pois, id ov-…): TripAdvisor
  // UNA volta per locale. Il voto, il numero di recensioni, la fascia di
  // prezzo e il location_id si salvano sulla riga (ta_*); per 30 giorni le
  // aperture successive leggono dalla tabella e non consumano quota
  // (search+details = 2 chiamate risparmiate a ogni apertura). Solo API
  // gratuite: Overture in tabella + TripAdvisor free tier.
  app.get("/api/locali/scheda", async (req, res) => {
    try {
      const id = String(req.query.id || '');
      if (!/^ov-[A-Za-z0-9_-]{8,80}$/.test(id)) return res.status(400).json({ error: 'id non valido' });
      if (!supabaseUrl || !supabaseServiceKey) return res.status(500).json({ error: 'Supabase non configurato' });
      const hdr = { apikey: supabaseServiceKey, Authorization: `Bearer ${supabaseServiceKey}`, 'Content-Type': 'application/json' };
      const rRow = await fetch(`${supabaseUrl}/rest/v1/locali_pois?id=eq.${encodeURIComponent(id)}&select=id,name,lat,lon,city,phone,website,ta_location_id,ta_rating,ta_num_reviews,ta_price_level,ta_updated_at,fsq_id,fsq_updated_at&limit=1`, { headers: hdr, signal: AbortSignal.timeout(8000) });
      const righe = rRow.ok ? await rRow.json() : [];
      const riga = righe?.[0];
      if (!riga) return res.status(404).json({ error: 'locale non trovato' });

      const fresco = riga.ta_updated_at && (Date.now() - new Date(riga.ta_updated_at).getTime()) < 30 * 86400000;
      const risposta = (extra: any = {}) => res.json({
        id: riga.id,
        location_id: riga.ta_location_id || null,
        rating: riga.ta_rating ?? null,
        num_reviews: riga.ta_num_reviews ?? null,
        price_level: riga.ta_price_level || null,
        web_url: null, // l'URL della pagina lo da' solo /details: non si inventa
        phone: riga.phone || null,
        website: riga.website || null,
        cercato: !!riga.ta_updated_at,
        ...extra,
      });
      if (fresco) return risposta({ fresh: true });

      const key = process.env.TRIPADVISOR_API_KEY || process.env.VITE_TRIPADVISOR_API_KEY;
      const taBudgetOk = key ? await tripAdvisorBudgetOk() : false;

      let locationId: string | null = null;
      const patch: any = {};
      if (taBudgetOk) {
        // Ricerca per nome vicino alle coordinate; si accetta il primo
        // risultato solo se sta entro 300 m (TripAdvisor riporta la
        // distanza in km).
        try {
          const sUrl = `https://api.content.tripadvisor.com/api/v1/location/search?searchQuery=${encodeURIComponent(riga.name)}&latLong=${riga.lat},${riga.lon}&radius=1&radiusUnit=km&category=restaurants&language=it&key=${key}`;
          const sRes = await axios.get(sUrl, { headers: { Accept: 'application/json' }, timeout: 8000 });
          const primo = (sRes.data?.data || [])[0];
          const dist = primo?.distance != null ? parseFloat(primo.distance) : null;
          if (primo?.location_id && (dist == null || dist <= 0.3)) locationId = String(primo.location_id);
        } catch { /* niente: si segna comunque il tentativo */ }

        patch.ta_updated_at = new Date().toISOString();
        if (locationId) {
          patch.ta_location_id = locationId;
          try {
            const dRes = await axios.get(`https://api.content.tripadvisor.com/api/v1/location/${locationId}/details?language=it&key=${key}`, { headers: { Accept: 'application/json' }, timeout: 8000 });
            const d = dRes.data || {};
            if (d.rating != null) patch.ta_rating = parseFloat(d.rating);
            if (d.num_reviews != null) patch.ta_num_reviews = parseInt(d.num_reviews, 10);
            if (d.price_level) patch.ta_price_level = String(d.price_level).slice(0, 12);
          } catch { /* dettagli mancanti: resta il location_id */ }
        }
      }

      // Fallback Foursquare (30/08/2026): SOLO se TripAdvisor non ha trovato
      // il locale o ha esaurito il budget mensile, E solo campi Pro gratuiti
      // (nome/indirizzo/telefono/sito). Niente voto/prezzo/foto: su
      // Foursquare sono Premium, mai gratis (si paga dalla prima chiamata) -
      // vedi FREE_FIELDS in /api/fsq/details. Riempie solo telefono/sito se
      // ancora mancanti sulla riga, e solo una volta ogni 30 giorni.
      const fsqStale = !riga.fsq_updated_at || (Date.now() - new Date(riga.fsq_updated_at).getTime()) >= 30 * 86400000;
      const fsqUseful = !riga.phone || !riga.website;
      if (!locationId && fsqStale && fsqUseful) {
        const fsqKey = process.env.FOURSQUARE_API_KEY || process.env.VITE_FOURSQUARE_API_KEY;
        if (fsqKey && (await foursquareBudgetOk())) {
          try {
            const fsqSearchUrl = `https://places-api.foursquare.com/places/search?ll=${riga.lat},${riga.lon}&query=${encodeURIComponent(riga.name)}&limit=1`;
            const fsqSearchRes = await axios.get(fsqSearchUrl, {
              headers: { Authorization: `Bearer ${fsqKey}`, Accept: 'application/json', 'X-Places-Api-Version': '2025-06-17' },
              timeout: 6000,
            });
            const fsqPlace = (fsqSearchRes.data?.results || [])[0];
            const fsqId = fsqPlace?.fsq_place_id || fsqPlace?.fsq_id;
            if (fsqId) {
              patch.fsq_id = String(fsqId);
              try {
                const fsqDetailsUrl = `https://places-api.foursquare.com/places/${fsqId}?fields=name,website,tel`;
                const fsqDetailsRes = await axios.get(fsqDetailsUrl, {
                  headers: { Authorization: `Bearer ${fsqKey}`, Accept: 'application/json', 'X-Places-Api-Version': '2025-06-17' },
                  timeout: 6000,
                });
                const fd = fsqDetailsRes.data || {};
                if (!riga.phone && fd.tel) patch.phone = String(fd.tel).slice(0, 40);
                if (!riga.website && fd.website) patch.website = String(fd.website).slice(0, 300);
              } catch { /* dettagli mancanti: resta il fsq_id */ }
            }
            patch.fsq_updated_at = new Date().toISOString();
          } catch { /* ricerca Foursquare fallita: si riprova al prossimo giro */ }
        }
      }

      if (Object.keys(patch).length > 0) {
        await fetch(`${supabaseUrl}/rest/v1/locali_pois?id=eq.${encodeURIComponent(id)}`, { method: 'PATCH', headers: { ...hdr, Prefer: 'return=minimal' }, body: JSON.stringify(patch), signal: AbortSignal.timeout(8000) }).catch(() => {});
        Object.assign(riga, patch);
      }
      return risposta({ fresh: taBudgetOk });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  // Proxy for Nominatim Reverse
  // Lingua per Nominatim (accept-language) da lista chiusa, default it.
  const nominatimLang = (raw: any): string => {
    const l = String(raw || 'it').slice(0, 2).toLowerCase();
    return ['it', 'en', 'fr', 'es', 'de', 'ru', 'zh'].includes(l) ? l : 'it';
  };
  // GeoNames (27/08/2026): stesso identico bisogno di nominatimQueue.ts —
  // "nome città da coordinate", niente indirizzo civico. findNearbyPlaceName
  // e' fatto apposta per questo, con una quota molto piu' larga di Nominatim
  // (che il client tiene a 1 richiesta/1,2s per la policy OSM). Se manca lo
  // username o GeoNames non risponde, si ripiega su Nominatim: nessuna
  // modifica lato client, la forma della risposta resta {address:{city}}.
  async function reverseGeoNames(lat: number, lon: number): Promise<string | null> {
    const username = process.env.GEONAMES_USERNAME;
    if (!username) return null;
    try {
      const url = `http://api.geonames.org/findNearbyPlaceNameJSON?lat=${lat}&lng=${lon}&username=${encodeURIComponent(username)}`;
      const r = await fetch(url, { signal: AbortSignal.timeout(5000) });
      if (!r.ok) return null;
      const data = await r.json();
      // status.value 18/19 = quota oraria/giornaliera esaurita: si ripiega
      // su Nominatim senza far fallire la richiesta dell'utente.
      if (data?.status) return null;
      const name = data?.geonames?.[0]?.name;
      return typeof name === 'string' && name ? name : null;
    } catch {
      return null;
    }
  }
  app.get("/api/nominatim/reverse", rateLimiter, async (req, res) => {
    try {
      const lat = parseFloat(String(req.query.lat)), lon = parseFloat(String(req.query.lon));
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) return res.status(400).json({ error: 'lat/lon non validi' });

      const geoNamesCity = await reverseGeoNames(lat, lon);
      if (geoNamesCity) {
        return res.json({ address: { city: geoNamesCity }, source: 'geonames' });
      }

      const lang = nominatimLang(req.query.lang || req.query.language || req.query['accept-language']);
      const url = `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json&accept-language=${lang}`;
      const nRes = await fetch(url, {
        headers: { "User-Agent": "AIAudioGuideApp/1.0" }
      });
      const nData = await nRes.json();
      res.json(nData);
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  // Proxy for Nominatim Search
  app.get("/api/nominatim/search", rateLimiter, async (req, res) => {
    try {
      const { q, countrycodes } = req.query;
      if (!q) return res.status(400).json({ error: 'q richiesto' });
      const lang = nominatimLang(req.query.lang || req.query.language || req.query['accept-language']);
      // Ricerca MONDIALE di default: il filtro countrycodes=it,sm,va rendeva
      // impossibile scaricare mappe/cercare città fuori dall'Italia. Il filtro
      // resta disponibile come parametro opzionale per i chiamanti che lo vogliono.
      const cc = countrycodes ? `&countrycodes=${encodeURIComponent(String(countrycodes))}` : "";

      // CACHE + FRENO + User-Agent vero (30/08/2026).
      //
      // Questa rotta chiamava l'istanza PUBBLICA di OSM senza cache, senza
      // freno e con lo User-Agent generico «AIAudioGuideApp/1.0». La politica
      // d'uso di Nominatim chiede l'opposto: un massimo di una richiesta al
      // secondo, un'applicazione identificabile con un contatto, e di mettere
      // in cache i risultati. Senza, il rischio concreto e' il blocco
      // dell'IP — e su Vercel l'IP e' condiviso, quindi si porterebbe giu'
      // anche il resto. Si riusa lo stesso freno e lo stesso User-Agent della
      // catena di searchPlaces, che erano gia' a norma.
      const chiaveCache = `nominatim_search_${crypto.createHash('md5').update(`${q}|${lang}|${cc}`).digest('hex')}`;
      const inCache = await getFromCache(chiaveCache);
      if (inCache?.text_content) {
        try { return res.json(JSON.parse(inCache.text_content)); } catch { /* cache corrotta: si richiede */ }
      }

      const attesa = nominatimLastCall + 1100 - Date.now();
      if (attesa > 0) await new Promise((r) => setTimeout(r, attesa));
      nominatimLastCall = Date.now();

      const url = `https://nominatim.openstreetmap.org/search?format=json${cc}&q=${encodeURIComponent(String(q).slice(0, 200))}&accept-language=${lang}&limit=5`;
      const nRes = await fetch(url, { headers: { "User-Agent": NOMINATIM_UA } });
      const nData = await nRes.json();
      if (Array.isArray(nData) && nData.length) saveToCache(chiaveCache, 'geocode', JSON.stringify(nData));
      res.json(nData);
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

